function renderCollections(){
 const filters=[['all','كل الشخصيات','All characters'],['omani','عُمانية','Omani'],['gulf','خليجية','Gulf'],['arab','عربية وعلمية','Arab & science'],['knights','فرسان وفارسات','Knights'],['sea','بحّارة وبحر','Sailors & sea'],['fantasy','خيال وفضاء','Fantasy & space'],['careers','مهن وأحلام','Jobs & dreams']];
 characterSection.innerHTML=`<div class="wrap"><div class="section-top"><div class="character-heading"><span class="overline">${t('هوية عُمانية… وأبطال من كل حكاية','AN OMANI HEART. A HERO FOR EVERY STORY.')}</span><h2>${t('أيّ شخصية تشبه خيال طفلك؟','Who will your child become?')}</h2><p>${t('اختَر الزي والشخصية بحرّية: عُمانية أو خليجية أو عربية، فارسًا أو بحّارًا أو مستكشفًا. تبقى روح عُمان حاضرة في الموقع وحكاياته.','Choose an Omani, Gulf or Arab outfit, a knight, a sailor or an explorer. Oman’s spirit stays at the heart of Hikaya.')}</p></div><button class="button outline" id="allCharactersCreate">${t('خصّص بطل الحكاية ✧','Design their hero ✧')}</button></div><div class="heritage-filters" role="group" aria-label="${t('تصفية الشخصيات','Filter characters')}">${filters.map(([id,a,e])=>`<button data-char-filter="${id}" class="${characterFilter===id?'active':''}" aria-pressed="${characterFilter===id}">${t(a,e)}</button>`).join('')}</div><div class="character-grid">${characters.filter(c=>characterFilter==='all'||c.group===characterFilter).map(c=>`<button class="character-card" data-character="${c.id}" aria-label="${t('اختيار','Choose')} ${esc(charName(c))}">${charArt(c).replace('</div>','<span class="character-choice">↗</span></div>')}<h3>${esc(charName(c))}</h3><p>${esc(c.tag[lang==='ar'?0:1])}</p></button>`).join('')}</div><div class="identity-ribbon"><strong>${t('أزياء متنوّعة، وجذور عُمانية.','Many outfits. Omani roots.')}</strong><span>${t('رسوم أصلية خيالية · اختيار الشخصية ينعكس في الغلاف والنص · تحويل صورة الطفل يحتاج تفعيل التوليد','Original fictional art · Character choice shapes the cover and text · Photo transformation requires activation')}</span></div></div>`;
 characterSection.querySelectorAll('[data-char-filter]').forEach(b=>b.onclick=()=>{characterFilter=b.dataset.charFilter;renderCollections()});
 characterSection.querySelectorAll('[data-character]').forEach(b=>b.onclick=()=>{const c=characterById(b.dataset.character);launchStory({character:c.id,world:c.world||(['sailor','diver'].includes(c.id)?'ocean':'forest'),narrative:c.group==='knights'?'knight':c.id==='sailor'?'sailor':'original',landmark:c.id==='sailor'?'sur':'gardens'})});
 $('#allCharactersCreate').onclick=()=>launchStory();
 historySection.innerHTML=`<div class="section-top"><div class="history-heading"><span class="overline">${t('من صفحات التاريخ… إلى دفتر طفلك','FROM THE PAGES OF HISTORY TO THEIR NOTEBOOK')}</span><h2>${t('حكايات حقيقية تُلهم أبطال الغد.','True stories for tomorrow’s heroes.')}</h2><p>${t('بحّارة وعلماء ورحّالة مسلمون، ومعالم عُمانية تستحق أن تُروى.','Muslim navigators, scientists and travelers, and Omani heritage worth discovering.')}</p></div></div><p class="history-preface">${t('حقائق مختصرة موثّقة في ٦ صفحات، داخل إطار قراءة متخيّل يكون الطفل راويه. صورة البطل تمثيل خيالي لطفلك، وليست صورة للشخصية التاريخية.','Six-page readings combine concise sourced facts with an imaginary reading frame narrated by your child. Hero illustrations represent a fictional child, not a portrait of the historical figure.')}</p><div class="history-grid">${historyTopics.map(h=>`<article class="history-card">${charArt(characterById(h.character))}<div class="history-copy"><span class="badge">${t('قراءة موثّقة · ٦ صفحات','Sourced reading · 6 pages')}</span><h3>${esc(charName(h))}</h3><p>${esc(h.subtitle[lang==='ar'?0:1])}</p><button class="button outline" data-history="${h.id}">${t('استكشف الحكاية ←','Explore this story →')}</button><a class="history-source" href="${h.source.url}" target="_blank" rel="noopener noreferrer">${t('المصدر التاريخي ↗','Historical source ↗')}</a></div></article>`).join('')}</div>`;
 historySection.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{const h=historyTopics.find(x=>x.id===b.dataset.history);launchStory({character:h.character,narrative:h.id,world:h.world,landmark:h.id==='bahla'?'bahla':'sur'})});
}
