 if(step===2&&story){for(const key of ['character','narrative','landmark','tone'])if(story[key])draft[key]=story[key]}
 draft.character=characterById(draft.character||'omani-boy').id;draft.narrative=draft.narrative||'original';draft.landmark=draft.landmark||'gardens';draft.tone=draft.tone||'omani';
